@lboue - Thanks for the PR. 

**Recommendation:** do not hard-restrict.
Put setTagList() on MatterEndPoint (generic)

#### Example:

``` cpp
// Allowed on any endpoint — common namespaces
Light1.setTagList({MatterTags::Position::Top, MatterTags::Number::One});
// Natural for switches — still just presets, not a gate
ButtonOn.setTagList({MatterTags::Switches::On, MatterTags::Position::Right});
// Escape hatch always available
ep.setTagList({MatterTags::make(ns, tag, "my-label")});
```

----------------

We could think of a more generic Semantic Tag interface that could apply for any endpoint (example: a device with 3 light endpint, each with a tag defined by the user).

``` cpp
// Named namespaces + values (Arduino-friendly, no magic numbers required)
namespace MatterTags {
  namespace Position {
    static constexpr uint8_t NS = 0x08;
    static constexpr MatterTag Left  {NS, 0};
    static constexpr MatterTag Right {NS, 1};
    static constexpr MatterTag Top   {NS, 2};
    static constexpr MatterTag Bottom{NS, 3};
    static constexpr MatterTag Middle{NS, 4};
  }
  namespace Number {
    static constexpr uint8_t NS = 0x07;
    static constexpr MatterTag One {NS, 1};
    static constexpr MatterTag Two {NS, 2};
    static constexpr MatterTag Three {NS, 3};
  }
  namespace Switches {
    static constexpr uint8_t NS = 0x43;
    static constexpr MatterTag On     {NS, 0};
    static constexpr MatterTag Off    {NS, 1};
    static constexpr MatterTag Toggle {NS, 2};
    static constexpr MatterTag Custom {NS, 8}; // use with .label
  }
  namespace Location {
    static constexpr uint8_t NS = 0x06;
    static constexpr MatterTag Indoor  {NS, 0};
    static constexpr MatterTag Outdoor {NS, 1};
 }
 ```
 
